CREATE TABLE IF NOT EXISTS matrix_repositories(repository_id INTEGER PRIMARY KEY,full_name TEXT NOT NULL UNIQUE,baseline_sha TEXT NOT NULL,matrix_version TEXT NOT NULL,matrix_digest TEXT NOT NULL,image_uri TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS matrix_deliveries(id TEXT PRIMARY KEY,payload_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS matrix_submissions(repository_id INTEGER NOT NULL,pr_number INTEGER NOT NULL,head_sha TEXT NOT NULL,updated_at TEXT NOT NULL,closed INTEGER NOT NULL DEFAULT 0,latest_run_id TEXT NOT NULL,PRIMARY KEY(repository_id,pr_number));
CREATE TABLE IF NOT EXISTS matrix_runs(id TEXT PRIMARY KEY,repository_id INTEGER NOT NULL,full_name TEXT NOT NULL,pr_number INTEGER NOT NULL,head_sha TEXT NOT NULL,baseline_sha TEXT NOT NULL,matrix_version TEXT NOT NULL,matrix_digest TEXT NOT NULL,image_uri TEXT NOT NULL,attempt INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL DEFAULT 'QUEUED' CHECK(state IN ('QUEUED','RUNNING','COMPLETED','FAILED','SUPERSEDED')),report TEXT,failure_code TEXT,check_run_id INTEGER,publication_status TEXT NOT NULL DEFAULT 'PENDING',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS matrix_runs_submission ON matrix_runs(repository_id,pr_number,created_at);
